// Ported from the Node app's Sequelize model CalendarEvent (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class CalendarEventConfiguration : IEntityTypeConfiguration<CalendarEvent>
{
    public void Configure(EntityTypeBuilder<CalendarEvent> builder)
    {
        builder.ToTable("calendar_events", t =>
        {
            t.HasCheckConstraint("CK_calendar_events_type", "[type] IN (N'holiday', N'exam', N'event', N'meeting', N'other')");
            t.HasCheckConstraint("CK_calendar_events_audience", "[audience] IN (N'all', N'staff', N'parents')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Title).HasColumnName("title").HasColumnType("nvarchar(160)").HasMaxLength(160).IsRequired();
        builder.Property(e => e.Type).HasColumnName("type").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'event'");
        builder.Property(e => e.StartDate).HasColumnName("start_date").HasColumnType("date");
        builder.Property(e => e.EndDate).HasColumnName("end_date").HasColumnType("date");
        builder.Property(e => e.Audience).HasColumnName("audience").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'all'");
        builder.Property(e => e.Description).HasColumnName("description").HasColumnType("nvarchar(500)").HasMaxLength(500);
    }
}
